import{_ as o,a as r,b as s,c as a,d as n,e,f as i,g,h as l,i as p,j as c}from"./chunks/notifications.BgueT9nY.js";import{_ as h,o as d,c as m,a2 as u}from"./chunks/framework.Bzj1XTnB.js";const w=JSON.parse('{"title":"शुरुआत करें","description":"Toonik में आपका पहला प्रोजेक्ट — होम स्क्रीन, प्रोजेक्ट बनाना और अपना काम सुरक्षित रखना।","frontmatter":{"lang":"hi","slug":"getting-started","order":1,"title":"शुरुआत करें","description":"Toonik में आपका पहला प्रोजेक्ट — होम स्क्रीन, प्रोजेक्ट बनाना और अपना काम सुरक्षित रखना।"},"headers":[],"relativePath":"hi/getting-started.md","filePath":"hi/getting-started.md"}'),_={name:"hi/getting-started.md"};function b(f,t,k,q,T,P){return d(),m("div",null,[...t[0]||(t[0]=[u('<h1 id="शुरुआत-करें" tabindex="-1">शुरुआत करें <a class="header-anchor" href="#शुरुआत-करें" aria-label="Permalink to &quot;शुरुआत करें&quot;">​</a></h1><p>Toonik फ़्रेम-दर-फ़्रेम एनिमेशन बनाने का ऐप है। आप एक तस्वीर बनाते हैं, नया फ़्रेम जोड़ते हैं, उसमें वही तस्वीर थोड़ी बदलकर बनाते हैं — और जब सारे फ़्रेम एक के बाद एक चलते हैं तो आपकी ड्रॉइंग हिलने लगती है। ऐप में सब कुछ मुफ़्त है, कोई अकाउंट नहीं बनाना पड़ता और कोई विज्ञापन नहीं है।</p><h2 id="होम-स्क्रीन" tabindex="-1">होम स्क्रीन <a class="header-anchor" href="#होम-स्क्रीन" aria-label="Permalink to &quot;होम स्क्रीन&quot;">​</a></h2><p><img src="'+o+'" alt="चार प्रोजेक्ट के साथ होम स्क्रीन"></p><ul><li><strong>Projects</strong> और <strong>Movies</strong> — दो टैब। बदलने के लिए बाएँ या दाएँ स्वाइप करें।</li><li><strong>☰ (मेन्यू)</strong> — साइड मेन्यू खोलता है (नीचे देखें)। गुलाबी बिंदु का मतलब है कि कुछ नया पढ़ने को है।</li><li><strong>🔔 (घंटी)</strong> — Toonik की ओर से आपकी सूचनाएँ। संख्या बताती है कितनी अभी पढ़ी नहीं गईं।</li><li><strong>गुलाबी गोला (ऊपर दाएँ)</strong> — Settings खोलता है।</li><li><strong>नीचे की पट्टी</strong> — <strong>Home</strong>, <strong>Objects</strong> (ऑब्जेक्ट लाइब्रेरी), <strong>+</strong> (नया प्रोजेक्ट), <strong>Learn</strong> (एनिमेशन के छोटे पाठ) और <strong>Settings</strong>।</li></ul><p>प्रोजेक्ट खोलने के लिए उस पर टैप करें। हर कार्ड पर छोटे लेबल बताते हैं कि एनिमेशन कितना लंबा है और उसकी रफ़्तार कितने फ़्रेम प्रति सेकंड (fps) है।</p><h3 id="साइड-मेन्यू" tabindex="-1">साइड मेन्यू <a class="header-anchor" href="#साइड-मेन्यू" aria-label="Permalink to &quot;साइड मेन्यू&quot;">​</a></h3><p><img src="'+r+'" alt="साइड मेन्यू"></p><p><strong>App settings</strong>, <strong>Object library</strong>, <strong>How to animate</strong> (पाठ), <strong>What&#39;s new</strong> (हर अपडेट में क्या आया), <strong>Notifications</strong>, <strong>About</strong>, <strong>Rate this app</strong> और <strong>Share Toonik</strong>।</p><h2 id="प्रोजेक्ट-बनाएँ" tabindex="-1">प्रोजेक्ट बनाएँ <a class="header-anchor" href="#प्रोजेक्ट-बनाएँ" aria-label="Permalink to &quot;प्रोजेक्ट बनाएँ&quot;">​</a></h2><p>नीचे गुलाबी <strong>+</strong> पर टैप करें।</p><p><img src="'+s+'" alt="नया प्रोजेक्ट स्क्रीन"></p><ol><li><p><strong>Project name</strong> — नाम लिखें, या &quot;My Animation 1&quot; ही रहने दें।</p></li><li><p><strong>Choose background</strong> — प्रीव्यू के नीचे चार बटन:</p><ul><li><strong>Presets</strong> — पेपर, सफ़ेद, ग्रिड, लाइन वाला पेपर, डॉट ग्रिड, आसमान, सूर्यास्त, रात का आसमान, घास का मैदान, ग्रीन स्क्रीन, काला और भी।</li><li><strong>Camera</strong> — फ़ोटो खींचें और उसके ऊपर ड्रॉ करें।</li><li><strong>Gallery</strong> — फ़ोन की कोई तस्वीर लगाएँ।</li><li><strong>Color</strong> — एक सादा रंग (कोई रंग चुनें या HEX कोड लिखें)।</li></ul><p><img src="'+a+'" alt="बैकग्राउंड प्रीसेट"></p></li><li><p><strong>Choose canvas size</strong> — YouTube, YouTube Shorts, Instagram, TikTok, स्टिकर वगैरह के लिए तैयार साइज़, या अपनी चौड़ाई-ऊँचाई ख़ुद लिखें (64 से 2048 पिक्सेल)।</p><p><img src="'+n+'" alt="कैनवास साइज़"></p></li><li><p><strong>Choose frames per second</strong> — हर सेकंड में कितनी ड्रॉइंग चलेंगी। शुरुआत के लिए <strong>12 fps</strong> अच्छा है। उछलती गेंद दिखाती है कि रफ़्तार कैसी दिखेगी।</p><p><img src="'+e+'" alt="फ़्रेम प्रति सेकंड"></p></li><li><p><strong>Create project</strong> पर टैप करें।</p></li></ol><blockquote><p><strong>ध्यान दें:</strong> प्रोजेक्ट बनने के बाद कैनवास का साइज़ नहीं बदला जा सकता। नाम, रफ़्तार और बैकग्राउंड कभी भी <strong>Project settings</strong> में बदल सकते हैं।</p></blockquote><h2 id="अपने-प्रोजेक्ट-सँभालें" tabindex="-1">अपने प्रोजेक्ट सँभालें <a class="header-anchor" href="#अपने-प्रोजेक्ट-सँभालें" aria-label="Permalink to &quot;अपने प्रोजेक्ट सँभालें&quot;">​</a></h2><p>किसी प्रोजेक्ट को चुनने के लिए उस पर <strong>देर तक दबाएँ</strong> (लॉन्ग-प्रेस)। कई चुनने हों तो और कार्ड पर टैप करें।</p><p><img src="'+i+'" alt="प्रोजेक्ट चुनना"></p><p>नीचे की पट्टी से आप:</p><ul><li>✏️ <strong>Rename</strong> — नाम बदलें (एक बार में एक प्रोजेक्ट)</li><li>⧉ <strong>Duplicate</strong> — &quot;… copy&quot; नाम से कॉपी बनाएँ</li><li><strong>Export project</strong> — पूरा प्रोजेक्ट <code>.flippa</code> फ़ाइल के रूप में शेयर करें: किसी को भेजें, बैकअप रखें या दूसरे फ़ोन पर खोलें</li><li>🗑 <strong>Delete</strong> — पहले पूछता है, और वापस नहीं आता</li></ul><p>चुनने का मोड बंद करने के लिए ऊपर <strong>✕</strong> पर टैप करें।</p><h3 id="क्रम-इम्पोर्ट-और-चुनना" tabindex="-1">क्रम, इम्पोर्ट और चुनना <a class="header-anchor" href="#क्रम-इम्पोर्ट-और-चुनना" aria-label="Permalink to &quot;क्रम, इम्पोर्ट और चुनना&quot;">​</a></h3><p>टैब के पास <strong>⋮</strong> पर टैप करें।</p><p><img src="'+g+'" alt="क्रम और इम्पोर्ट मेन्यू"></p><ul><li><strong>Sort by</strong> — Last modified, Name या Date created के हिसाब से।</li><li><strong>Import project</strong> — Toonik का बैकअप (<code>.flippa</code>) या <strong>FlipaClip प्रोजेक्ट (<code>.fc</code>)</strong> खोलें। यह नए प्रोजेक्ट के रूप में जुड़ता है; आपका कोई पुराना प्रोजेक्ट नहीं बदलता। FlipaClip से लेयर और ड्रॉइंग आ जाती हैं (लेयर इफ़ेक्ट और आवाज़ नहीं)।</li><li><strong>Select</strong> — चुनने का मोड शुरू करें।</li></ul><h3 id="टाइम-लैप्स-रिकॉर्डिंग" tabindex="-1">टाइम-लैप्स रिकॉर्डिंग <a class="header-anchor" href="#टाइम-लैप्स-रिकॉर्डिंग" aria-label="Permalink to &quot;टाइम-लैप्स रिकॉर्डिंग&quot;">​</a></h3><p>Toonik आपकी बनाई हर लकीर रिकॉर्ड करके उसका टाइम-लैप्स वीडियो बना सकता है। प्रोजेक्ट चुनें, ऊपर <strong>⋯</strong> पर टैप करें और <strong>Time-Lapse Recording</strong> चालू करें। बाद में उसी जगह से <strong>Share Time-Lapse</strong> करें। टाइम-लैप्स वीडियो <strong>Movies</strong> टैब में भी दिखते हैं।</p><p><img src="'+l+'" alt="प्रोजेक्ट विकल्प"></p><h2 id="आपका-काम-अपने-आप-सेव-होता-है" tabindex="-1">आपका काम अपने आप सेव होता है <a class="header-anchor" href="#आपका-काम-अपने-आप-सेव-होता-है" aria-label="Permalink to &quot;आपका काम अपने आप सेव होता है&quot;">​</a></h2><p>Toonik ड्रॉ करते समय सेव करता रहता है (शुरू में हर 10 सेकंड पर — Settings में बदल सकते हैं), और एडिटर से निकलते समय या दूसरे ऐप पर जाते समय भी। आपके प्रोजेक्ट आपके फ़ोन में रहते हैं; आपकी ड्रॉइंग कहीं अपलोड नहीं होती।</p><h2 id="what-s-new-और-सूचनाएँ" tabindex="-1">What&#39;s new और सूचनाएँ <a class="header-anchor" href="#what-s-new-और-सूचनाएँ" aria-label="Permalink to &quot;What&#39;s new और सूचनाएँ&quot;">​</a></h2><p><strong>What&#39;s new</strong> (साइड मेन्यू) में हर अपडेट और उसमें क्या बदला, सब लिखा है। <strong>घंटी</strong> में Toonik के आख़िरी 15 संदेश रहते हैं, छूटे हुए भी। किसी संदेश पर टैप करें तो उसका लिंक खुलता है।</p><p><img src="'+p+'" alt="What&#39;s new"></p><p><img src="'+c+'" alt="सूचनाएँ"></p>',33)])])}const C=h(_,[["render",b]]);export{w as __pageData,C as default};
